import pdfplumber

with pdfplumber.open("workspace/population.pdf") as pdf:
    print(f"Pages: {len(pdf.pages)}")
    for i, page in enumerate(pdf.pages[:3]):
        tables = page.extract_tables()
        print(f"\n--- Page {i+1}: {len(tables)} tables ---")
        for t in tables[:2]:
            print(f"Rows: {len(t)}, Cols: {len(t[0]) if t else 0}")
            for row in t[:5]:
                print(row)
        text = page.extract_text()
        if text:
            print("TEXT PREVIEW:", text[:500])

